#!/usr/bin/env python3
from __future__ import annotations
import base64,re,shutil,subprocess,sys,time
from pathlib import Path

PATCH_ID="MEMEFLOW_DISCOVERY_PLATFORM_DROPDOWN_V2"
OLD_PATCH="MEMEFLOW_DISCOVERY_SETTINGS_UI_V1"
STAMP=time.strftime("%Y%m%d-%H%M%S")
RUNTIME=base64.b64decode("").decode("utf-8")

def log(msg):
    print("[DISCOVERY-UI-V2] "+str(msg),flush=True)

def find_root():
    candidates=[
        Path.cwd(),Path.cwd()/"memeflow-app",
        Path.home()/"workspace",Path.home()/"workspace"/"memeflow-app",
        Path("/home/runner/workspace"),Path("/home/runner/workspace/memeflow-app")
    ]
    for root in candidates:
        try: root=root.resolve()
        except Exception: continue
        if (root/"system.js").is_file() and (root/"app-server.mjs").is_file():
            return root
    for base in [Path("/home/runner/workspace"),Path.cwd()]:
        if not base.exists(): continue
        for p in base.glob("**/system.js"):
            if (p.parent/"app-server.mjs").is_file():
                return p.parent.resolve()
    raise RuntimeError("MEMEFLOW system.js/app-server.mjs root not found")

ROOT=find_root()
SYSTEM=ROOT/"system.js"
SERVER=ROOT/"app-server.mjs"
BACK=ROOT/(".discovery-ui-v2-backup-"+STAMP)
BACK.mkdir(parents=True,exist_ok=True)
changed=[]

def rel(p): return p.resolve().relative_to(ROOT.resolve())

def backup(p):
    if p in changed:return
    d=BACK/rel(p);d.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,d);changed.append(p)

def write(p,text):
    backup(p);p.write_text(text,encoding="utf-8");log("patched "+str(rel(p)))

def rollback(reason):
    log("ERROR: "+str(reason))
    for p in reversed(changed):
        src=BACK/rel(p)
        if src.exists():
            shutil.copy2(src,p);log("restored "+str(rel(p)))
    log("ROLLBACK COMPLETE");sys.exit(1)

def remove_old_v1(text):
    marker="// "+OLD_PATCH
    start=text.find(marker)
    if start<0:return text,False
    tail=text[start:]
    if "window.__mfDiscoverySettingsUiV1" not in tail:
        return text,False

    next_marker=tail.find("\n// MEMEFLOW_",len(marker))
    region=tail if next_marker<0 else tail[:next_marker]
    end=region.rfind("})();")
    if end<0:
        return text,False
    end+=len("})();")
    cleaned=text[:start].rstrip()+"\n\n"+tail[end:].lstrip()
    return cleaned,True

try:
    log("root: "+str(ROOT))
    server=SERVER.read_text(encoding="utf-8")
    if "/api/discovery-source" not in server:
        raise RuntimeError("Discovery Router /api/discovery-source is missing; keep V1.1 installed first.")

    text=SYSTEM.read_text(encoding="utf-8")
    if PATCH_ID in text:
        log("V2 already installed");sys.exit(0)

    text,removed=remove_old_v1(text)
    if removed: log("removed superseded Discovery settings V1 UI")
    else: log("old V1 UI code was not removed; V2 will suppress its panel safely")

    text=text.rstrip()+"\n\n// "+PATCH_ID+"\n"+RUNTIME+"\n"
    write(SYSTEM,text)

    result=subprocess.run(["node","--check",str(SYSTEM)],cwd=ROOT,capture_output=True,text=True)
    if result.returncode!=0:
        raise RuntimeError("node --check system.js failed:\n"+(result.stderr or result.stdout))

    final=SYSTEM.read_text(encoding="utf-8")
    for token in [
        PATCH_ID,"mfdx-platform-card-v2","mfdx-platform-menu-v2",
        "/api/discovery-source","PUMP_ONLY_RULES",
        "mfdx-dex-inactive-v2","mfdx-hybrid-note-v2"
    ]:
        if token not in final: raise RuntimeError("validation missing: "+token)

    log("system.js syntax OK")
    log("INSTALL COMPLETE")
    log("PLATFORM card now opens Pump.fun / DEX / Hybrid dropdown")
    log("separate Discovery source panel is superseded")
    log("DEX-incompatible fields are muted and interaction-blocked")
    log("HYBRID keeps Pump-only fields editable and marks them Pump-branch-only")
    log("DEX-incompatible groups: bonding curve, total fees, developer/creator, bundle, sniper")
    log("shared Risk / Trading / market / holder settings remain active")
    log("backup: "+str(BACK))
    log("Hard-refresh System settings.")

except Exception as exc:
    rollback(exc)
